

-- ============================================================================
--  YPI NURUL ILMI BEKASI — SKEMA POSTGRESQL (SUPABASE)
--  Migrasi dari MySQL `web_nurul_ilmi` (Laravel 12) ke Supabase.
--
--  Cakupan: 10 tabel bisnis + 2 tabel pendukung (user_roles,
--  comment_rate_limits). Tabel auth Laravel (users, sessions,
--  password_reset_tokens) DIGANTI oleh Supabase Auth, tabel infra
--  (cache, jobs, failed_jobs, migrations) dibuang.
--
--  Semua `bigint` memakai GENERATED BY DEFAULT AS IDENTITY (bukan ALWAYS)
--  supaya ID lama bisa di-insert eksplisit saat migrasi data.
--
--  Cara pakai:
--    1. Jalankan file ini di Supabase SQL Editor (atau `supabase db push`).
--    2. Jalankan `supabase/data.sql` (hasil migrasi 124 baris).
--    3. Jalankan `supabase/storage-policies.sql` bila bucket belum ada.
--
--  Referensi: RANCANGAN-MIGRASI-SUPABASE.md
-- ============================================================================

create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------------------
--  1. TABEL BISNIS
-- ---------------------------------------------------------------------------

create table if not exists public.categories (
  id         bigint generated by default as identity primary key,
  name       text not null,
  slug       text not null unique,
  created_at timestamptz,
  updated_at timestamptz
);

create table if not exists public.units (
  id          bigint generated by default as identity primary key,
  name        text not null,
  slug        text not null unique,
  group_type  text not null default 'main' check (group_type in ('main', 'sigma')),
  description text,
  created_at  timestamptz,
  updated_at  timestamptz
);

create table if not exists public.tags (
  id         bigint generated by default as identity primary key,
  name       text not null unique,
  slug       text not null unique,
  created_at timestamptz,
  updated_at timestamptz
);

create table if not exists public.articles (
  id           bigint generated by default as identity primary key,
  category_id  bigint references public.categories(id) on delete set null,
  title_id     text not null,
  content_id   text not null,
  title_en     text,
  content_en   text,
  image        text,
  author_name  text not null default 'Admin',
  -- Relasi ke Supabase Auth. Menulis siapa yang membuat artikel.
  author_id    uuid references auth.users(id) on delete set null,
  -- Unit pemilik artikel. NULL = artikel umum (khusus super_admin).
  unit_id      bigint references public.units(id) on delete set null,
  status       text not null default 'published' check (status in ('published', 'draft')),
  published_at timestamptz,
  views        bigint not null default 0,
  created_at   timestamptz,
  updated_at   timestamptz
);

create index if not exists articles_category_id_idx on public.articles(category_id);
create index if not exists articles_status_idx on public.articles(status);
create index if not exists articles_published_at_idx on public.articles(published_at desc);
create index if not exists articles_author_id_idx on public.articles(author_id);
create index if not exists articles_unit_id_idx on public.articles(unit_id);

create table if not exists public.article_media (
  id         bigint generated by default as identity primary key,
  article_id bigint not null references public.articles(id) on delete cascade,
  type       text not null default 'image' check (type in ('image', 'video')),
  path       text not null,
  mime_type  text,
  caption    text,
  sort_order integer not null default 0,
  created_at timestamptz,
  updated_at timestamptz
);

create index if not exists article_media_article_id_idx on public.article_media(article_id, sort_order);

create table if not exists public.article_tags (
  id         bigint generated by default as identity primary key,
  article_id bigint not null references public.articles(id) on delete cascade,
  tag_id     bigint not null references public.tags(id) on delete cascade,
  created_at timestamptz,
  updated_at timestamptz
);

create index if not exists article_tags_article_id_idx on public.article_tags(article_id);
create index if not exists article_tags_tag_id_idx on public.article_tags(tag_id);

create table if not exists public.comments (
  id         bigint generated by default as identity primary key,
  article_id bigint not null references public.articles(id) on delete cascade,
  name       text not null,
  comment    text not null,
  email      text,
  -- Kolom baru: moderasi. Semua komentar publik masuk dengan status 'pending'.
  status     text not null default 'published' check (status in ('published', 'pending', 'spam')),
  -- Kolom baru: hash IP untuk rate limit anti-spam.
  ip_hash    text,
  created_at timestamptz,
  updated_at timestamptz
);

create index if not exists comments_article_id_idx on public.comments(article_id);
create index if not exists comments_status_idx on public.comments(status);

create table if not exists public.facilities (
  id           bigint generated by default as identity primary key,
  name         text not null,
  slug         text not null unique,
  description  text,
  icon         text,
  is_published boolean not null default false,
  group_type   text not null default 'main' check (group_type in ('main', 'sigma')),
  sort_order   integer not null default 0,
  created_at   timestamptz,
  updated_at   timestamptz
);

create index if not exists facilities_group_published_idx on public.facilities(group_type, is_published);
create index if not exists facilities_sort_order_idx on public.facilities(sort_order);

create table if not exists public.facility_photos (
  id          bigint generated by default as identity primary key,
  facility_id bigint not null references public.facilities(id) on delete cascade,
  image_path  text not null,
  caption     text,
  alt_text    text,
  sort_order  integer not null default 0,
  is_cover    boolean not null default false,
  created_at  timestamptz,
  updated_at  timestamptz
);

create index if not exists facility_photos_facility_id_idx on public.facility_photos(facility_id, sort_order);

create table if not exists public.facility_unit (
  id          bigint generated by default as identity primary key,
  facility_id bigint not null references public.facilities(id) on delete cascade,
  unit_id     bigint not null references public.units(id) on delete cascade,
  created_at  timestamptz,
  updated_at  timestamptz,
  constraint facility_unit_unique unique (facility_id, unit_id)
);

create index if not exists facility_unit_unit_id_idx on public.facility_unit(unit_id);

-- ---------------------------------------------------------------------------
--  2. TABEL PENDUKUNG
-- ---------------------------------------------------------------------------

-- Sumber kebenaran peran. Peran hanya boleh diubah lewat service_role atau
-- oleh super_admin (kecuali baris miliknya sendiri).
--
-- Lima peran:
--   super_admin      -> seluruh unit
--   tk_nurul_ilmi    -> unit TK Nurul Ilmi
--   sd_nurul_ilmi    -> unit SD Nurul Ilmi
--   smp_nurul_ilmi   -> unit SMP Nurul Ilmi
--   sigma_nurul_ilmi -> unit TK Sigma + Daycare Sigma
create table if not exists public.user_roles (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  role       text not null check (role in ('super_admin', 'tk_nurul_ilmi', 'sd_nurul_ilmi', 'smp_nurul_ilmi', 'sigma_nurul_ilmi')),
  granted_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

-- Unit yang boleh dikelola oleh seorang admin unit. Super_admin tidak punya
-- baris di sini (= seluruh unit).
create table if not exists public.user_units (
  user_id    uuid not null references auth.users(id) on delete cascade,
  unit_id    bigint not null references public.units(id) on delete cascade,
  granted_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (user_id, unit_id)
);

create index if not exists user_units_unit_id_idx on public.user_units(unit_id);

-- Constraint role ikut diperbarui bila tabel sudah ada dari versi lama.
alter table public.user_roles drop constraint if exists user_roles_role_check;
alter table public.user_roles
  add constraint user_roles_role_check
  check (role in ('super_admin', 'tk_nurul_ilmi', 'sd_nurul_ilmi', 'smp_nurul_ilmi', 'sigma_nurul_ilmi'));

-- Anti-spam: sliding window per ip_hash.
create table if not exists public.comment_rate_limits (
  id         bigint generated by default as identity primary key,
  ip_hash    text not null,
  created_at timestamptz not null default now()
);

create index if not exists comment_rate_limits_ip_created_idx
  on public.comment_rate_limits(ip_hash, created_at desc);

-- ---------------------------------------------------------------------------
--  3. FUNGSI
-- ---------------------------------------------------------------------------

-- Peran efektif user saat ini. SECURITY DEFINER supaya bisa dipanggil
-- dari policy RLS lain tanpa memicu RLS pada user_roles.
create or replace function public.current_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from public.user_roles where user_id = auth.uid();
$$;

revoke all on function public.current_role() from public;
grant execute on function public.current_role() to authenticated;

-- ---------------------------------------------------------------------------
-- Fungsi bantu RBAC per unit.
--
-- Semua SECURITY DEFINER + search_path terkunci supaya bisa dipakai di dalam
-- policy RLS tanpa memicu RLS tabel yang dibaca (user_roles, user_units,
-- units, articles, facility_unit).
-- ---------------------------------------------------------------------------

-- True bila pemanggil adalah super_admin.
create or replace function public.is_super_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.user_roles
    where user_id = auth.uid() and role = 'super_admin'
  );
$$;

revoke all on function public.is_super_admin() from public;
grant execute on function public.is_super_admin() to authenticated;

-- Daftar unit yang boleh dikelola pemanggil.
create or replace function public.user_unit_ids()
returns bigint[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(array_agg(unit_id), '{}'::bigint[])
  from public.user_units
  where user_id = auth.uid();
$$;

revoke all on function public.user_unit_ids() from public;
grant execute on function public.user_unit_ids() to authenticated;

-- True bila pemanggil adalah staf: super_admin atau admin unit yang punya unit.
create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_super_admin() or cardinality(public.user_unit_ids()) > 0;
$$;

revoke all on function public.is_staff() from public;
grant execute on function public.is_staff() to authenticated;

-- True bila pemanggil boleh mengelola unit tertentu.
create or replace function public.can_manage_unit(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_super_admin()
      or (p_unit_id is not null and p_unit_id = any(public.user_unit_ids()));
$$;

revoke all on function public.can_manage_unit(bigint) from public;
grant execute on function public.can_manage_unit(bigint) to authenticated;

-- True bila pemanggil boleh mengelola sebuah artikel.
create or replace function public.can_manage_article(p_article_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_super_admin()
      or exists (
        select 1 from public.articles a
        where a.id = p_article_id
          and a.unit_id = any(public.user_unit_ids())
      );
$$;

revoke all on function public.can_manage_article(bigint) from public;
grant execute on function public.can_manage_article(bigint) to authenticated;

-- True bila pemanggil boleh mengelola sebuah fasilitas.
-- Fasilitas tidak punya unit_id; kepemilikan unit dibaca dari facility_unit.
create or replace function public.can_manage_facility(p_facility_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_super_admin()
      or exists (
        select 1 from public.facility_unit fu
        where fu.facility_id = p_facility_id
          and fu.unit_id = any(public.user_unit_ids())
      );
$$;

revoke all on function public.can_manage_facility(bigint) from public;
grant execute on function public.can_manage_facility(bigint) to authenticated;

-- Folder (segmen pertama path) yang boleh ditulis admin unit.
create or replace function public.user_unit_slugs()
returns text[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(array_agg(u.slug), '{}'::text[])
  from public.user_units uu
  join public.units u on u.id = uu.unit_id
  where uu.user_id = auth.uid();
$$;

revoke all on function public.user_unit_slugs() from public;
grant execute on function public.user_unit_slugs() to authenticated;

-- IP klien, dibaca dari header proxy Supabase.
create or replace function public.client_ip()
returns text
language sql
stable
as $$
  select nullif(
    split_part(
      coalesce(
        current_setting('request.headers', true)::json ->> 'x-forwarded-for',
        current_setting('request.headers', true)::json ->> 'x-real-ip',
        ''
      ),
      ',', 1
    ),
    ''
  );
$$;

revoke all on function public.client_ip() from public;
grant execute on function public.client_ip() to anon, authenticated;

-- Increment counter baca artikel. Client publik tidak boleh UPDATE
-- langsung (RLS), jadi lewat RPC.
create or replace function public.increment_article_views(p_article_id bigint)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v bigint;
begin
  update public.articles
     set views = views + 1
   where id = p_article_id
     and status = 'published'
  returning views into v;

  return coalesce(v, 0);
end;
$$;

revoke all on function public.increment_article_views(bigint) from public;
grant execute on function public.increment_article_views(bigint) to anon, authenticated;

-- Submit komentar publik: validasi + honeypot + rate limit, SELALU status
-- 'pending' supaya wajib dimoderasi admin sebelum tayang.
create or replace function public.submit_comment(
  p_article_id bigint,
  p_name      text,
  p_email     text,
  p_comment   text,
  p_hp        text default null
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ip   text := public.client_ip();
  v_hash text := encode(
    extensions.digest(coalesce(v_ip, 'unknown') || 'ypi-nurul-ilmi', 'sha256'), 'hex'
  );
  v_id   bigint;
begin
  -- Honeypot: field tersembunyi harus kosong. Kembalikan -1 tanpa pesan
  -- supaya bot tidak belajar proteksinya.
  if p_hp is not null and length(trim(p_hp)) > 0 then
    return -1;
  end if;

  if length(coalesce(trim(p_name), '')) < 2 then
    raise exception 'validasi gagal: nama minimal 2 karakter';
  end if;

  if length(coalesce(trim(p_comment), '')) < 3 then
    raise exception 'validasi gagal: komentar minimal 3 karakter';
  end if;

  if length(coalesce(p_name, '')) > 255 or length(coalesce(p_comment, '')) > 5000 then
    raise exception 'validasi gagal: isian terlalu panjang';
  end if;

  if p_email is not null and p_email <> '' and p_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'validasi gagal: format email tidak valid';
  end if;

  -- Rate limit: maksimal 5 komentar per jam per IP.
  if (select count(*) from public.comment_rate_limits
        where ip_hash = v_hash
          and created_at > now() - interval '1 hour') >= 5 then
    raise exception 'terlalu sering';
  end if;

  -- Artikel harus ada dan published.
  if not exists (select 1 from public.articles
                  where id = p_article_id and status = 'published') then
    raise exception 'artikel tidak ditemukan';
  end if;

  insert into public.comments (article_id, name, email, comment, status, ip_hash)
  values (p_article_id, trim(p_name), nullif(trim(coalesce(p_email, '')), ''),
          trim(p_comment), 'pending', v_hash)
  returning id into v_id;

  insert into public.comment_rate_limits (ip_hash, created_at) values (v_hash, now());

  return v_id;
end;
$$;

revoke all on function public.submit_comment(bigint, text, text, text, text) from public;
grant execute on function public.submit_comment(bigint, text, text, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------------
--  4. ROW LEVEL SECURITY
-- ---------------------------------------------------------------------------

alter table public.categories       enable row level security;
alter table public.units            enable row level security;
alter table public.tags             enable row level security;
alter table public.articles         enable row level security;
alter table public.article_media    enable row level security;
alter table public.article_tags     enable row level security;
alter table public.comments         enable row level security;
alter table public.facilities       enable row level security;
alter table public.facility_photos  enable row level security;
alter table public.facility_unit    enable row level security;
alter table public.user_roles       enable row level security;
alter table public.user_units       enable row level security;
alter table public.comment_rate_limits enable row level security;

-- ---- categories: SELECT publik, tulis super_admin -------------------------
drop policy if exists "categories_select_public" on public.categories;
create policy "categories_select_public" on public.categories
  for select to anon, authenticated using (true);

drop policy if exists "categories_insert_staff" on public.categories;
create policy "categories_insert_staff" on public.categories
  for insert to authenticated with check (public.is_super_admin());

drop policy if exists "categories_update_staff" on public.categories;
create policy "categories_update_staff" on public.categories
  for update to authenticated using (public.is_super_admin())
  with check (public.is_super_admin());

drop policy if exists "categories_delete_staff" on public.categories;
create policy "categories_delete_staff" on public.categories
  for delete to authenticated using (public.is_super_admin());

-- ---- tags: sama seperti categories ---------------------------------------
drop policy if exists "tags_select_public" on public.tags;
create policy "tags_select_public" on public.tags
  for select to anon, authenticated using (true);

drop policy if exists "tags_insert_staff" on public.tags;
create policy "tags_insert_staff" on public.tags
  for insert to authenticated with check (public.is_super_admin());

drop policy if exists "tags_update_staff" on public.tags;
create policy "tags_update_staff" on public.tags
  for update to authenticated using (public.is_super_admin())
  with check (public.is_super_admin());

drop policy if exists "tags_delete_staff" on public.tags;
create policy "tags_delete_staff" on public.tags
  for delete to authenticated using (public.is_super_admin());

-- ---- units: SELECT publik, tulis admin -----------------------------------
drop policy if exists "units_select_public" on public.units;
create policy "units_select_public" on public.units
  for select to anon, authenticated using (true);

drop policy if exists "units_insert_admin" on public.units;
create policy "units_insert_admin" on public.units
  for insert to authenticated with check (public.is_super_admin());

drop policy if exists "units_update_admin" on public.units;
create policy "units_update_admin" on public.units
  for update to authenticated using (public.is_super_admin())
  with check (public.is_super_admin());

drop policy if exists "units_delete_admin" on public.units;
create policy "units_delete_admin" on public.units
  for delete to authenticated using (public.is_super_admin());

-- ---- articles -------------------------------------------------------------
-- anon  : hanya status 'published'
-- staf  : semua baris
-- admin unit : baris unitnya sendiri (lihat articles_select_authenticated)
drop policy if exists "articles_select_public" on public.articles;
create policy "articles_select_public" on public.articles
  for select to anon using (status = 'published');

drop policy if exists "articles_select_authenticated" on public.articles;
create policy "articles_select_authenticated" on public.articles
  for select to authenticated using (
    status = 'published'
    or public.is_super_admin()
    or unit_id = any(public.user_unit_ids())
  );

drop policy if exists "articles_insert_staff" on public.articles;
create policy "articles_insert_staff" on public.articles
  for insert to authenticated with check (
    public.is_super_admin()
    or (unit_id is not null and unit_id = any(public.user_unit_ids()))
  );

drop policy if exists "articles_update_staff" on public.articles;
create policy "articles_update_staff" on public.articles
  for update to authenticated
  using (public.is_super_admin() or unit_id = any(public.user_unit_ids()))
  with check (
    public.is_super_admin()
    or (unit_id is not null and unit_id = any(public.user_unit_ids()))
  );

drop policy if exists "articles_delete_admin" on public.articles;
create policy "articles_delete_admin" on public.articles
  for delete to authenticated using (
    public.is_super_admin() or unit_id = any(public.user_unit_ids())
  );

-- ---- article_media: mengikuti aturan artikel induknya ---------------------
drop policy if exists "article_media_select_public" on public.article_media;
create policy "article_media_select_public" on public.article_media
  for select to anon using (
    exists (select 1 from public.articles a
             where a.id = article_media.article_id and a.status = 'published')
  );

drop policy if exists "article_media_select_authenticated" on public.article_media;
create policy "article_media_select_authenticated" on public.article_media
  for select to authenticated using (
    public.can_manage_article(article_id)
    or exists (
      select 1 from public.articles a
      where a.id = article_media.article_id and a.status = 'published'
    )
  );

drop policy if exists "article_media_insert_staff" on public.article_media;
create policy "article_media_insert_staff" on public.article_media
  for insert to authenticated with check (public.can_manage_article(article_id));

drop policy if exists "article_media_update_staff" on public.article_media;
create policy "article_media_update_staff" on public.article_media
  for update to authenticated using (public.can_manage_article(article_id))
  with check (public.can_manage_article(article_id));

drop policy if exists "article_media_delete_staff" on public.article_media;
create policy "article_media_delete_staff" on public.article_media
  for delete to authenticated using (public.can_manage_article(article_id));

-- ---- article_tags: mengikuti aturan artikel induknya ----------------------
drop policy if exists "article_tags_select_public" on public.article_tags;
create policy "article_tags_select_public" on public.article_tags
  for select to anon using (
    exists (select 1 from public.articles a
             where a.id = article_tags.article_id and a.status = 'published')
  );

drop policy if exists "article_tags_select_authenticated" on public.article_tags;
create policy "article_tags_select_authenticated" on public.article_tags
  for select to authenticated using (
    public.can_manage_article(article_id)
    or exists (
      select 1 from public.articles a
      where a.id = article_tags.article_id and a.status = 'published'
    )
  );

drop policy if exists "article_tags_insert_staff" on public.article_tags;
create policy "article_tags_insert_staff" on public.article_tags
  for insert to authenticated with check (public.can_manage_article(article_id));

drop policy if exists "article_tags_update_staff" on public.article_tags;
create policy "article_tags_update_staff" on public.article_tags
  for update to authenticated using (public.can_manage_article(article_id))
  with check (public.can_manage_article(article_id));

drop policy if exists "article_tags_delete_staff" on public.article_tags;
create policy "article_tags_delete_staff" on public.article_tags
  for delete to authenticated using (public.can_manage_article(article_id));

-- ---- comments -------------------------------------------------------------
-- INSERT publik TIDAK ada policy: wajib lewat RPC submit_comment().
drop policy if exists "comments_select_public" on public.comments;
create policy "comments_select_public" on public.comments
  for select to anon using (status = 'published');

drop policy if exists "comments_select_authenticated" on public.comments;
create policy "comments_select_authenticated" on public.comments
  for select to authenticated using (
    status = 'published'
    or public.is_super_admin()
    or exists (
      select 1 from public.articles a
      where a.id = comments.article_id
        and a.unit_id = any(public.user_unit_ids())
    )
  );

drop policy if exists "comments_update_staff" on public.comments;
create policy "comments_update_staff" on public.comments
  for update to authenticated using (
    public.is_super_admin()
    or exists (
      select 1 from public.articles a
      where a.id = comments.article_id
        and a.unit_id = any(public.user_unit_ids())
    )
  )
  with check (
    public.is_super_admin()
    or exists (
      select 1 from public.articles a
      where a.id = comments.article_id
        and a.unit_id = any(public.user_unit_ids())
    )
  );

drop policy if exists "comments_delete_staff" on public.comments;
create policy "comments_delete_staff" on public.comments
  for delete to authenticated using (
    public.is_super_admin()
    or exists (
      select 1 from public.articles a
      where a.id = comments.article_id
        and a.unit_id = any(public.user_unit_ids())
    )
  );

-- ---- facilities -----------------------------------------------------------
drop policy if exists "facilities_select_public" on public.facilities;
create policy "facilities_select_public" on public.facilities
  for select to anon using (is_published = true);

drop policy if exists "facilities_select_authenticated" on public.facilities;
create policy "facilities_select_authenticated" on public.facilities
  for select to authenticated using (true);

drop policy if exists "facilities_insert_staff" on public.facilities;
create policy "facilities_insert_staff" on public.facilities
  for insert to authenticated with check (public.is_staff());

drop policy if exists "facilities_update_staff" on public.facilities;
create policy "facilities_update_staff" on public.facilities
  for update to authenticated using (public.can_manage_facility(id))
  with check (public.can_manage_facility(id));

drop policy if exists "facilities_delete_staff" on public.facilities;
create policy "facilities_delete_staff" on public.facilities
  for delete to authenticated using (public.can_manage_facility(id));

-- ---- facility_photos: mengikuti fasilitas induknya -----------------------
drop policy if exists "facility_photos_select_public" on public.facility_photos;
create policy "facility_photos_select_public" on public.facility_photos
  for select to anon using (
    exists (select 1 from public.facilities f
             where f.id = facility_photos.facility_id and f.is_published = true)
  );

drop policy if exists "facility_photos_select_authenticated" on public.facility_photos;
create policy "facility_photos_select_authenticated" on public.facility_photos
  for select to authenticated using (true);

drop policy if exists "facility_photos_insert_staff" on public.facility_photos;
create policy "facility_photos_insert_staff" on public.facility_photos
  for insert to authenticated with check (
    public.can_manage_facility(facility_id)
    /* Fasilitas baru milik unit ini belum punya tautan unit, jadi belum
       bisa dihitung can_manage_facility(). */
    or (
      public.is_staff()
      and not exists (
        select 1 from public.facility_unit fu where fu.facility_id = facility_photos.facility_id
      )
    )
  );

drop policy if exists "facility_photos_update_staff" on public.facility_photos;
create policy "facility_photos_update_staff" on public.facility_photos
  for update to authenticated using (public.can_manage_facility(facility_id))
  with check (public.can_manage_facility(facility_id));

drop policy if exists "facility_photos_delete_staff" on public.facility_photos;
create policy "facility_photos_delete_staff" on public.facility_photos
  for delete to authenticated using (public.can_manage_facility(facility_id));

-- ---- facility_unit --------------------------------------------------------
drop policy if exists "facility_unit_select_public" on public.facility_unit;
create policy "facility_unit_select_public" on public.facility_unit
  for select to anon, authenticated using (true);

drop policy if exists "facility_unit_insert_staff" on public.facility_unit;
create policy "facility_unit_insert_staff" on public.facility_unit
  for insert to authenticated with check (
    public.is_super_admin() or unit_id = any(public.user_unit_ids())
  );

drop policy if exists "facility_unit_update_staff" on public.facility_unit;
create policy "facility_unit_update_staff" on public.facility_unit
  for update to authenticated
  using (public.is_super_admin() or unit_id = any(public.user_unit_ids()))
  with check (public.is_super_admin() or unit_id = any(public.user_unit_ids()));

drop policy if exists "facility_unit_delete_staff" on public.facility_unit;
create policy "facility_unit_delete_staff" on public.facility_unit
  for delete to authenticated using (
    public.is_super_admin() or unit_id = any(public.user_unit_ids())
  );

-- ---- user_roles: super_admin mengelola, tapi tidak baris miliknya sendiri --
drop policy if exists "user_roles_select_own" on public.user_roles;
create policy "user_roles_select_own" on public.user_roles
  for select to authenticated using (user_id = auth.uid() or public.is_super_admin());

drop policy if exists "user_roles_insert_super" on public.user_roles;
create policy "user_roles_insert_super" on public.user_roles
  for insert to authenticated with check (
    public.is_super_admin() and user_id <> auth.uid()
  );

drop policy if exists "user_roles_update_super" on public.user_roles;
create policy "user_roles_update_super" on public.user_roles
  for update to authenticated
  using (public.is_super_admin() and user_id <> auth.uid())
  with check (public.is_super_admin() and user_id <> auth.uid());

drop policy if exists "user_roles_delete_super" on public.user_roles;
create policy "user_roles_delete_super" on public.user_roles
  for delete to authenticated using (
    public.is_super_admin() and user_id <> auth.uid()
  );

-- ---- user_units: super_admin menetapkan unit yang boleh dikelola ---------
drop policy if exists "user_units_select_own" on public.user_units;
create policy "user_units_select_own" on public.user_units
  for select to authenticated using (user_id = auth.uid() or public.is_super_admin());

drop policy if exists "user_units_insert_super" on public.user_units;
create policy "user_units_insert_super" on public.user_units
  for insert to authenticated with check (
    public.is_super_admin() and user_id <> auth.uid()
  );

drop policy if exists "user_units_update_super" on public.user_units;
create policy "user_units_update_super" on public.user_units
  for update to authenticated
  using (public.is_super_admin() and user_id <> auth.uid())
  with check (public.is_super_admin() and user_id <> auth.uid());

drop policy if exists "user_units_delete_super" on public.user_units;
create policy "user_units_delete_super" on public.user_units
  for delete to authenticated using (
    public.is_super_admin() and user_id <> auth.uid()
  );

-- ---- comment_rate_limits: hanya server (RPC) yang boleh akses ----------
-- Tidak ada policy sama sekali -> default DENY untuk anon & authenticated.

-- ---------------------------------------------------------------------------
--  5. BUCKET & KEBIJAKAN STORAGE
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'media', 'media', true, 26214400,
  array['image/jpeg', 'image/png', 'image/webp', 'video/mp4', 'video/webm']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "media_public_read" on storage.objects;
create policy "media_public_read" on storage.objects
  for select using (bucket_id = 'media');

drop policy if exists "media_staff_insert" on storage.objects;
create policy "media_staff_insert" on storage.objects
  for insert to authenticated with check (
    bucket_id = 'media'
    and (
      public.is_super_admin()
      or (storage.foldername(name))[1] = any(public.user_unit_slugs())
    )
  );

drop policy if exists "media_staff_update" on storage.objects;
create policy "media_staff_update" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'media'
    and (
      public.is_super_admin()
      or exists (
        select 1 from public.article_media am
        where am.path = name and public.can_manage_article(am.article_id)
      )
      or exists (
        select 1 from public.facility_photos fp
        where fp.image_path = name and public.can_manage_facility(fp.facility_id)
      )
    )
  )
  with check (
    bucket_id = 'media'
    and (
      public.is_super_admin()
      or (storage.foldername(name))[1] = any(public.user_unit_slugs())
    )
  );

drop policy if exists "media_staff_delete" on storage.objects;
create policy "media_staff_delete" on storage.objects
  for delete to authenticated using (
    bucket_id = 'media'
    and (
      public.is_super_admin()
      or exists (
        select 1 from public.article_media am
        where am.path = name and public.can_manage_article(am.article_id)
      )
      or exists (
        select 1 from public.facility_photos fp
        where fp.image_path = name and public.can_manage_facility(fp.facility_id)
      )
    )
  );

-- ---------------------------------------------------------------------------
--  6. PENJAGA: views tidak boleh diubah langsung oleh client
-- ---------------------------------------------------------------------------
-- articles.views hanya boleh naik lewat RPC increment_article_views().
-- Policy UPDATE di bawah tetap diperlukan untuk admin yayasan dan admin unit, tetapi
--_views_ tidak dikecualikan karena Supabase tidak mendukung CHECK kolom
-- pada policy. Sebagai gantinya, trigger berikut menolak UPDATE dari client
-- yang mengubah views secara langsung (session role = anon/authenticated).

create or replace function public.guard_article_views()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.views is distinct from old.views
     and current_user in ('anon', 'authenticated') then
    raise exception 'kolom views hanya dapat diubah lewat increment_article_views()';
  end if;

  return new;
end;
$$;

drop trigger if exists articles_guard_views on public.articles;
create trigger articles_guard_views
  before update on public.articles
  for each row execute function public.guard_article_views();

-- ---------------------------------------------------------------------------
--  7. PESAN SELAMAT DATANG
-- ---------------------------------------------------------------------------
comment on table public.user_roles is
  'Sumber kebenaran peran: super_admin, tk_nurul_ilmi, sd_nurul_ilmi, smp_nurul_ilmi, sigma_nurul_ilmi. Hanya super_admin yang boleh menulis, dan tidak boleh mengubah baris miliknya sendiri.';
comment on table public.user_units is
  'Unit yang boleh dikelola oleh seorang admin unit. Super_admin tidak punya baris di sini (= seluruh unit).';
comment on table public.comment_rate_limits is
  'Sliding window anti-spam komentar, ditulis dari RPC submit_comment().';
comment on column public.articles.author_id is
  'Relasi ke Supabase Auth. Menulis siapa yang membuat artikel.';
comment on column public.articles.unit_id is
  'Unit pemilik artikel. NULL = artikel umum (khusus super_admin).';
comment on column public.comments.status is
  'Moderasi komentar. Komentar dari publik selalu masuk sebagai pending.';

-- ---------------------------------------------------------------------------
--  8. RESET SEQUENCE (dipakai script migrasi data)
-- ---------------------------------------------------------------------------
-- Memuat data lewat PostgREST (scripts/migrate-data.mjs) tidak menjalankan
-- select setval(...) yang ada di supabase/data.sql. Fungsi ini mengembalikan
-- sequence ke max(id)+1 untuk seluruh tabel yang memakai identity.
-- Hanya service_role yang boleh memanggilnya.

create or replace function public.reset_sequences()
returns void
language sql
security definer
set search_path = public
as $$
  select setval(pg_get_serial_sequence('public.categories', 'id'), coalesce((select max(id) from public.categories), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.units', 'id'), coalesce((select max(id) from public.units), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.tags', 'id'), coalesce((select max(id) from public.tags), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.articles', 'id'), coalesce((select max(id) from public.articles), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.article_media', 'id'), coalesce((select max(id) from public.article_media), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.article_tags', 'id'), coalesce((select max(id) from public.article_tags), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.comments', 'id'), coalesce((select max(id) from public.comments), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.facilities', 'id'), coalesce((select max(id) from public.facilities), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.facility_photos', 'id'), coalesce((select max(id) from public.facility_photos), 0) + 1, false);
  select setval(pg_get_serial_sequence('public.facility_unit', 'id'), coalesce((select max(id) from public.facility_unit), 0) + 1, false);
$$;

revoke all on function public.reset_sequences() from public;
grant execute on function public.reset_sequences() to service_role;
